notes:
/* ONLY THE DIGITS THAT CHANGE ROLL. Each digit is keyed by its
   place and its value, so 1,299 → 1,300 turns three wheels, each a
   beat after the one to its right, the way a carry travels. */
<AnimatePresence mode="popLayout">
  <motion.span key={digit}
    initial={{ y: up ? "100%" : "-100%" }} animate={{ y: 0 }}
    exit={{ y: up ? "-100%" : "100%" }}
    transition={{ delay: place * 0.04 }} />
</AnimatePresence>

/* the heart: squeeze, swell past its size, settle */
/* the like: the heart vanishes, a disc blooms and hollows into
   a ring (a border as wide as the radius, going to 0), seven pairs
   of confetti fly off it, and the heart springs back past its size */
@keyframes bloom { 40% { scale: 1; border-width: 17px } 100% { scale: 1.12; border-width: 0 } }
